// ====================================================================
// PARSE CONFIG ARC
// Kredensial Kirimi TIDAK pernah ditulis plaintext di node — selalu dibaca
// dari tab CONFIG. Pola sama persis dengan "Parse Config FU" di workflow
// Follow-up (keputusan #5 di Pending Waiting Changes).
// ====================================================================
const rows = $input.all().map(i => i.json);

const cfg = {};
for (const r of rows) {
  const k = String(r.key || r.Key || '').trim();
  if (!k) continue;
  const v = (r.value !== undefined && r.value !== null)
    ? r.value
    : ((r.Value !== undefined && r.Value !== null) ? r.Value : '');
  cfg[k] = v;
}

const num = (k, d) => { const n = Number(cfg[k]); return Number.isFinite(n) ? n : d; };
// Sheets kadang mengembalikan nomor telepon sebagai angka ("628228...212.0").
// Buang ekor desimalnya DULU, baru sisakan digit — kalau tidak, ".0" berubah
// jadi dua digit palsu di ujung nomor.
const digits = v => String(v === undefined || v === null ? '' : v)
  .trim().replace(/\.0+$/, '').replace(/\D/g, '');

// Lead yang masih "hangat" tidak diarsipkan. Default 60 hari.
// Ubah lewat CONFIG key `stats_archive_idle_days` — tanpa menyentuh kode.
let idleDays = num('stats_archive_idle_days', 60);
if (idleDays < 7) idleDays = 7;        // lantai keras: jangan pernah arsipkan lead seminggu terakhir
if (idleDays > 3650) idleDays = 3650;

// Laporan housekeeping ini untuk Steven, bukan untuk admin klien.
// Isi CONFIG `maintenance_phone` dengan nomor WA-mu; kalau kosong jatuh ke admin_phone.
const reportPhone = digits(cfg.maintenance_phone) || digits(cfg.admin_phone);

return [{ json: {
  config: {
    kirimi_user_code: String(cfg.kirimi_user_code || '').trim(),
    kirimi_secret: String(cfg.kirimi_secret || '').trim(),
    kirimi_device_id: String(cfg.kirimi_device_id || '').trim(),
    report_phone: reportPhone,
    // Nomor tim sendiri: kalau sampai nyangkut di STATS, jangan pernah diarsipkan.
    protected_numbers: [cfg.admin_phone, cfg.admin_phone_display, cfg.field_team_phone, cfg.media_team_phone]
      .map(digits).filter(Boolean),
    idle_days: idleDays,
  },
  now_epoch: Math.floor(Date.now() / 1000),
} }];

// ====================================================================
// PLAN ARCHIVE — STATS housekeeping tiap 3 bulan (Persada Cisoka Residence)
//
// BEDA MENDASAR dari cleanup The Scholars: STATS di sini adalah DATABASE
// LEAD, bukan sekadar state chat. Menghapus satu baris = kehilangan
// lead_source, unit_interest, budget_range, riwayat survey, dan counter
// follow-up milik klien. Karena itu alurnya:
//     ARSIP dulu -> VERIFIKASI baca-ulang -> baru HAPUS.
// Bukan hapus-langsung.
//
// TETAP TINGGAL DI STATS (tidak diarsipkan):
//   1. bot_mode = OFF             -> sedang dipegang manusia / tim lapangan
//   2. survey_status = scheduled  -> ada jadwal survey aktif
//   3. flag_survey = Y            -> sudah survey; lead paling berharga
//   4. aktivitas < idle_days      -> masih hangat. Kalau dihapus: VIRA nyapa
//                                    ulang seperti orang asing DAN
//                                    follow_up_count balik ke 0 sehingga
//                                    lead lama kena follow-up dari awal lagi
//   5. nomor admin/tim sendiri    -> jangan pernah disentuh
//   6. tanpa timestamp apa pun    -> umurnya tak bisa dipastikan; sengaja
//                                    TIDAK diarsipkan, tapi dilaporkan
//                                    supaya bisa dicek manual
//
// Penghapusan memakai nomor baris yang BENAR-BENAR dibaca run ini, bukan
// "baris 2..N" — jadi lead yang masuk setelah node Read tidak ikut kena.
// ====================================================================

const base = $('Parse Config ARC').first().json;
const cfg = base.config;
const now = base.now_epoch;
const cutoff = now - cfg.idle_days * 86400;

const norm = v => String(v === undefined || v === null ? '' : v).trim().toUpperCase();
const digits = v => String(v === undefined || v === null ? '' : v)
  .trim().replace(/\.0+$/, '').replace(/\D/g, '');
const YES = new Set(['Y', 'YA', 'YES', 'TRUE', '1', 'SUDAH', 'DONE']);

// Kolom yang bisa menandakan "kapan terakhir ada aktivitas". Diambil yang paling baru.
const TS_COLS = ['last_reply_ts', 'last_follow_up_ts', 'buffer_done_ts', 'debounce_ts',
                 'pending_survey_ts', 'unit_interest_ts', 'budget_range_ts',
                 'nama_lengkap_ts', 'lokasi_kerja_ts'];

function parseTanggal(v) {
  const s = String(v === undefined || v === null ? '' : v).trim();
  if (!s) return 0;
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);              // 2026-08-21
  if (m) return Math.floor(Date.UTC(+m[1], +m[2] - 1, +m[3]) / 1000);
  m = s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})/);          // 21/08/2026
  if (m) return Math.floor(Date.UTC(+m[3], +m[2] - 1, +m[1]) / 1000);
  return 0;
}

function lastActivity(r) {
  let best = 0;
  for (const c of TS_COLS) {
    let n = Number(String(r[c] === undefined || r[c] === null ? '' : r[c]).trim());
    if (!Number.isFinite(n) || n <= 0) continue;
    if (n > 1e12) n = Math.floor(n / 1000);   // epoch milidetik -> detik
    if (n > best) best = n;
  }
  if (!best) {
    // Cadangan terakhir: kolom tanggal yang ditulis dalam format manusia.
    best = parseTanggal(r['Tanggal Chat Terakhir']) || parseTanggal(r['Tanggal Chat Pertama']);
  }
  return best;
}

// --- Periode arsip -------------------------------------------------
// Workflow jalan tanggal 1 Jan/Apr/Jul/Okt, jadi kuartal yang diarsipkan
// adalah kuartal KEMARIN. Dihitung dari H-1 supaya tidak salah lompat.
const pParts = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Asia/Jakarta', year: 'numeric', month: '2-digit',
}).formatToParts(new Date((now - 86400) * 1000));
const pYear = (pParts.find(x => x.type === 'year') || {}).value;
const pMonth = Number((pParts.find(x => x.type === 'month') || {}).value || 1);
const periode = pYear + '-Q' + Math.ceil(pMonth / 3);

const archivedAt = new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Asia/Jakarta', year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false,
}).format(new Date(now * 1000));

const empty = extra => [{ json: Object.assign({
  periode, archivedAt, idleDays: cfg.idle_days,
  totalDataRows: 0, archiveCount: 0, keepCount: 0,
  blocks: [], blockCount: 0, archiveRows: [], noTsRows: [],
  reasons: { off: 0, scheduled: 0, sudah_survey: 0, masih_hangat: 0, nomor_tim: 0, tanpa_timestamp: 0 },
}, extra) }];

const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && typeof r === 'object'
            && r.row_number !== undefined
            && Number(r.row_number) >= 2);

if (!rows.length) {
  console.log('STATS kosong / hanya header — tidak ada yang diarsipkan.');
  return empty({ report: '[VIRA-PCR] STATS Archive — ' + periode + '\n\nSTATS kosong, tidak ada yang diarsipkan.' });
}

// Guard: pastikan yang terbaca benar-benar tab STATS dengan skema yang diharapkan.
// Lebih baik workflow gagal berisik daripada mengarsip/menghapus tab yang salah.
const sample = rows[0];
const REQUIRED = ['No WA', 'bot_mode', 'survey_status', 'flag_survey', 'last_reply_ts'];
const missing = REQUIRED.filter(c => !(c in sample));
if (missing.length) {
  throw new Error('Kolom wajib tidak ada di sheet yang terbaca: ' + missing.join(', ')
    + '. Tab yang terbaca kemungkinan bukan STATS, atau skemanya berubah. ARSIP DIBATALKAN.');
}

const archiveRows = [];
const archiveRowNums = [];
const noTsRows = [];
const reasons = { off: 0, scheduled: 0, sudah_survey: 0, masih_hangat: 0, nomor_tim: 0, tanpa_timestamp: 0 };

for (const r of rows) {
  let keep = null;

  if (norm(r.bot_mode) === 'OFF') keep = 'off';
  else if (norm(r.survey_status) === 'SCHEDULED') keep = 'scheduled';
  else if (YES.has(norm(r.flag_survey))) keep = 'sudah_survey';
  else if (cfg.protected_numbers.indexOf(digits(r['No WA'])) !== -1) keep = 'nomor_tim';
  else {
    const act = lastActivity(r);
    if (!act) keep = 'tanpa_timestamp';
    else if (act >= cutoff) keep = 'masih_hangat';
  }

  if (keep) {
    reasons[keep]++;
    if (keep === 'tanpa_timestamp') {
      noTsRows.push({ row: Number(r.row_number), no_wa: String(r['No WA'] || '').trim() });
    }
    continue;
  }

  const copy = Object.assign({}, r);
  delete copy.row_number;          // kolom bawaan n8n, bukan kolom asli sheet
  copy.archived_ts = archivedAt;
  copy.periode = periode;
  archiveRows.push(copy);
  archiveRowNums.push(Number(r.row_number));
}

// --- Blok penghapusan ----------------------------------------------
// Nomor baris yang mau dihapus dikelompokkan jadi blok kontigu, lalu diurutkan
// MENURUN. Menghapus dari bawah ke atas membuat nomor baris di atasnya tetap
// valid setelah blok di bawahnya hilang.
archiveRowNums.sort((a, b) => a - b);
const blocks = [];
for (const n of archiveRowNums) {
  const last = blocks[blocks.length - 1];
  if (last && n === last.startRow + last.count) last.count++;
  else blocks.push({ startRow: n, count: 1 });
}
blocks.reverse();

const keepCount = rows.length - archiveRows.length;

// --- Laporan WA ------------------------------------------------------
const lines = [];
lines.push('[VIRA-PCR] STATS Archive — ' + periode);
lines.push('');
if (!archiveRows.length) {
  lines.push('Tidak ada baris yang perlu diarsipkan.');
  lines.push('STATS: ' + rows.length + ' baris data, semuanya masih aktif atau dilindungi.');
} else {
  lines.push('Diarsipkan   : ' + archiveRows.length + ' baris -> tab STATS_ARCHIVE');
  lines.push('Sisa di STATS: ' + keepCount + ' baris');
  lines.push('');
  lines.push('Yang tetap tinggal:');
  lines.push('- Dipegang manusia (bot_mode OFF) : ' + reasons.off);
  lines.push('- Jadwal survey aktif (scheduled) : ' + reasons.scheduled);
  lines.push('- Sudah survey (flag_survey Y)    : ' + reasons.sudah_survey);
  lines.push('- Masih hangat (< ' + cfg.idle_days + ' hari)' + '        : ' + reasons.masih_hangat);
  if (reasons.nomor_tim) lines.push('- Nomor admin/tim                 : ' + reasons.nomor_tim);
}
if (reasons.tanpa_timestamp) {
  lines.push('');
  lines.push('PERLU DICEK: ' + reasons.tanpa_timestamp + ' baris tanpa timestamp apa pun — '
    + 'umurnya tidak bisa dipastikan jadi sengaja TIDAK diarsipkan.');
  lines.push('Baris: ' + noTsRows.slice(0, 15).map(x => x.row + '(' + (x.no_wa || '-') + ')').join(', ')
    + (noTsRows.length > 15 ? ', +' + (noTsRows.length - 15) + ' lagi' : ''));
}
const report = lines.join('\n');

console.log('STATS archive ' + periode + ': ' + rows.length + ' baris data | '
  + archiveRows.length + ' diarsipkan dalam ' + blocks.length + ' blok | ' + keepCount + ' tetap tinggal.');
if (blocks.length > 40) {
  console.warn('⚠️ ' + blocks.length + ' blok hapus — mendekati kuota tulis Google Sheets (60/menit). '
    + 'Node Delete sudah retry otomatis, tapi pantau hasilnya.');
}

return [{ json: {
  periode, archivedAt,
  idleDays: cfg.idle_days,
  totalDataRows: rows.length,
  archiveCount: archiveRows.length,
  keepCount,
  blocks,
  blockCount: blocks.length,
  reasons,
  noTsRows,
  archiveRows,
  report,
} }];

// Pecah archiveRows jadi item terpisah supaya node Append menulis satu baris
// per item. `row_number` sudah dibuang di node Plan archive.
const plan = $('Plan archive').first().json;
const rows = plan.archiveRows || [];

if (!rows.length) {
  console.log('Tidak ada baris untuk diarsipkan.');
  return [];
}

console.log('Menyalin ' + rows.length + ' baris ke STATS_ARCHIVE (periode ' + plan.periode
  + ') SEBELUM apa pun dihapus dari STATS.');
return rows.map(r => ({ json: r }));

// Node Google Sheets jalan sekali PER ITEM. Kalau N item hasil Append diteruskan
// apa adanya, node Read & Delete di belakangnya ikut jalan N kali dan menghapus
// blok yang salah berulang-ulang. Ciutkan jadi tepat 1 item.
const plan = $('Plan archive').first().json;
console.log('Append selesai — node mengembalikan ' + $input.all().length + ' item '
  + '(rencana ' + plan.archiveCount + '). Verifikasi baca-ulang menyusul.');
return [{ json: plan }];

// ====================================================================
// GERBANG KESELAMATAN
// Tidak ada satu baris pun dihapus dari STATS sebelum salinannya TERBUKTI
// ada di STATS_ARCHIVE. Buktinya bukan "node Append tidak error", tapi hasil
// BACA ULANG tab arsip: hitung baris ber-periode run ini.
// Kalau kurang dari rencana -> lempar error. STATS utuh, tinggal jalankan
// ulang setelah penyebabnya beres.
// ====================================================================
const plan = $('Plan archive').first().json;
const expected = Number(plan.archiveCount || 0);

const found = $input.all()
  .map(i => i.json)
  .filter(r => r && String(r.periode === undefined || r.periode === null ? '' : r.periode).trim() === plan.periode)
  .length;

if (found < expected) {
  throw new Error('Verifikasi arsip GAGAL: hanya ' + found + ' dari ' + expected
    + ' baris periode ' + plan.periode + ' yang ketemu di STATS_ARCHIVE. '
    + 'STATS TIDAK DIHAPUS. Cek header tab STATS_ARCHIVE (wajib ada kolom `periode` '
    + 'dan `archived_ts`) lalu jalankan ulang.');
}

console.log('Verifikasi arsip OK: ' + found + ' baris periode ' + plan.periode
  + ' aman di STATS_ARCHIVE. Lanjut hapus ' + plan.blockCount + ' blok dari STATS.');
return [{ json: plan }];

// Keluarkan satu item per blok. Node Delete jalan sekali per item, jadi urutan
// item = urutan penghapusan — dan blocks sudah diurutkan MENURUN di Plan archive
// supaya penghapusan berjalan dari bawah ke atas.
const plan = $('Plan archive').first().json;
const blocks = plan.blocks || [];

if (!blocks.length) {
  console.log('Tidak ada blok untuk dihapus.');
  return [];
}

console.log('Menghapus ' + blocks.length + ' blok (bawah -> atas): '
  + blocks.map(b => b.startRow + '..' + (b.startRow + b.count - 1)).join(', '));
return blocks.map(b => ({ json: b }));

// Ciutkan lagi jadi 1 item supaya notifikasi WA terkirim sekali, bukan sekali per blok.
const plan = $('Plan archive').first().json;
console.log('STATS bersih: ' + plan.archiveCount + ' baris pindah ke arsip, '
  + plan.keepCount + ' baris tetap tinggal.');
return [{ json: plan }];
